import { useEffect, useState } from "react";

export default function Reviews() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState(null);
  const [editMessage, setEditMessage] = useState("");
  const [editRating, setEditRating] = useState(5);

  // ================= FETCH REVIEWS =================
  const fetchReviews = async () => {
    try {
      const res = await fetch("http://localhost:5001/admin/reviews", {
        headers: {
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
      });
      const data = await res.json();
      setReviews(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReviews();
  }, []);

  // ================= UPDATE STATUS =================
  const updateStatus = async (id, status) => {
    try {
      await fetch(`http://localhost:5001/admin/reviews/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
        body: JSON.stringify({ status }),
      });

      setReviews((prev) =>
        prev.map((r) => (r.id === id ? { ...r, status } : r))
      );
    } catch (err) {
      console.error(err);
    }
  };

  // ================= START EDIT =================
  const startEdit = (review) => {
    setEditingId(review.id);
    setEditMessage(review.message);
    setEditRating(review.rating);
  };

  // ================= SAVE UPDATE =================
  const saveUpdate = async (id) => {
    try {
      await fetch(`http://localhost:5001/admin/reviews/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
        body: JSON.stringify({
          message: editMessage,
          rating: editRating,
        }),
      });

      setReviews((prev) =>
        prev.map((r) =>
          r.id === id
            ? { ...r, message: editMessage, rating: editRating }
            : r
        )
      );

      setEditingId(null);
    } catch (err) {
      console.error(err);
    }
  };

  // ================= UI =================
  return (
    <div className="p-10 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-8">
        Customer Reviews
      </h1>

      {loading ? (
        <p className="text-gray-400">Loading reviews...</p>
      ) : reviews.length === 0 ? (
        <p className="text-gray-500">No reviews found</p>
      ) : (
        <div className="space-y-6 max-w-5xl">
          {reviews.map((review) => (
            <div
              key={review.id}
              className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
                         border border-yellow-500/30 rounded-2xl
                         p-6 shadow-xl"
            >
              {/* HEADER */}
              <div className="flex justify-between items-center mb-3">
                <h2 className="text-lg font-semibold text-yellow-400">
                  {review.name}
                </h2>

                <span
                  className={`text-xs px-3 py-1 rounded-full font-semibold ${
                    review.status === "Active"
                      ? "bg-green-500/20 text-green-400"
                      : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {review.status}
                </span>
              </div>

              {/* EDIT MODE */}
              {editingId === review.id ? (
                <>
                  {/* Rating */}
                  <select
                    value={editRating}
                    onChange={(e) => setEditRating(Number(e.target.value))}
                    className="mb-3 bg-black border border-yellow-500 rounded px-3 py-1 text-white"
                  >
                    {[1, 2, 3, 4, 5].map((n) => (
                      <option key={n} value={n}>
                        {n} Star
                      </option>
                    ))}
                  </select>

                  {/* Message */}
                  <textarea
                    value={editMessage}
                    onChange={(e) => setEditMessage(e.target.value)}
                    className="w-full bg-black border border-yellow-500 rounded p-3 text-sm text-white mb-3"
                    rows={3}
                  />

                  <div className="flex gap-3">
                    <button
                      onClick={() => saveUpdate(review.id)}
                      className="bg-yellow-400 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Save
                    </button>

                    <button
                      onClick={() => setEditingId(null)}
                      className="bg-gray-600 text-white px-4 py-1 rounded-lg"
                    >
                      Cancel
                    </button>
                  </div>
                </>
              ) : (
                <>
                  {/* RATING */}
                  <div className="flex items-center mb-3">
                    {[1, 2, 3, 4, 5].map((n) => (
                      <span
                        key={n}
                        className={
                          n <= review.rating
                            ? "text-yellow-400 text-lg"
                            : "text-gray-600 text-lg"
                        }
                      >
                        ★
                      </span>
                    ))}
                  </div>

                  {/* MESSAGE */}
                  <p className="text-gray-300 text-sm mb-4">
                    {review.message}
                  </p>

                  {/* DATE */}
                  <p className="text-xs text-gray-500 mb-4">
                    {new Date(review.created_at).toLocaleString()}
                  </p>

                  {/* ACTIONS */}
                  <div className="flex gap-3 flex-wrap">
                    <button
                      onClick={() => startEdit(review)}
                      className="bg-blue-500 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Update
                    </button>

                    {review.status !== "Active" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Active")
                        }
                        className="bg-green-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Approve
                      </button>
                    )}

                    {review.status !== "Hidden" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Hidden")
                        }
                        className="bg-red-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Hide
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
